/* ---------------- video formats: the 24 the 06AV0000 test report asks for ---------------- */
const RATE = {'23.98':24000/1001,'24':24,'25':25,'29.97':30000/1001,'30':30,'50':50,'59.94':60000/1001,'60':60};
const GEN720 = {'60':0x00,'59.94':0x00,'30':0x02,'29.97':0x02,'50':0x04,'25':0x06,'24':0x08,'23.98':0x08};
const GEN1080P = {'30':0x0B,'29.97':0x0B,'25':0x0D,'24':0x10,'23.98':0x10};
function mkFmt(std, scan, r){
  const m1001 = /\.9|23\.98/.test(r) && r!=='29.97x';
  const f = {std, m1001, r};
  if (std==='SD'){
    const p = scan==='525i';
    Object.assign(f,{id:'SD-'+scan, name:'SD '+scan+' '+r, lines:p?525:625, fps:p?30000/1001:25, il:true, pclk:27e6, bitrate:270e6, gen:p?0x16:0x18, m1001:p});
  } else if (std==='HD'){
    const L = scan==='720p'?750:1125;
    const fps = scan==='1080i'? RATE[r]/2 : RATE[r];
    Object.assign(f,{id:'HD-'+scan+'-'+r, name:'HD '+scan+' '+r, lines:L, fps, il:scan==='1080i', pclk:74.25e6/(m1001?1.001:1), bitrate:1.485e9/(m1001?1.001:1),
      gen: scan==='720p'?GEN720[r] : scan==='1080i'?(r==='50'?0x0C:0x0A) : GEN1080P[r]});
  } else {
    Object.assign(f,{id:std+'-'+r, name:(std==='3GA'?'3G-A':'3G-B')+' 1080p '+r, lines:1125, fps:RATE[r], il:false, pclk:148.5e6/(m1001?1.001:1), bitrate:2.97e9/(m1001?1.001:1),
      gen: r==='50'?0x2D:0x2B});
  }
  // lines per second on the 20-bit (or 10-bit SD) interface. Level B carries two 1080i-structured links word-interleaved
  // (SMPTE 425 level B-DL), so one interface line holds a line of each link (INFERRED from the standard, not the archive)
  f.lps = std==='3GB' ? f.lines*f.fps/2 : f.lines*f.fps;
  f.words = Math.round(f.pclk/f.lps);
  f.spl = 48000/f.lps;               // audio samples per line (per group)
  f.ui = 1/f.bitrate;
  return f;
}
const FORMATS = [
  ...['50','59.94','60'].map(r=>mkFmt('3GA','1080p',r)),
  ...['50','59.94','60'].map(r=>mkFmt('3GB','1080p',r)),
  ...['23.98','24','25','29.97','30','50','59.94','60'].map(r=>mkFmt('HD','720p',r)),
  ...['23.98','24','25','29.97','30'].map(r=>mkFmt('HD','1080p',r)),
  ...['50','59.94','60'].map(r=>mkFmt('HD','1080i',r)),
  mkFmt('SD','525i','59.94'), mkFmt('SD','625i','50'),
];
const FMT = {}; FORMATS.forEach(f=>FMT[f.id]=f);
const STDCODE = {SD:1, HD:2, '3GA':3, '3GB':4};      // gs2970a.h LOCK_SD … LOCK_3GB (and sdi_format on the panel)

