function boardSVG(side){
  const L = side==='before' ? PNP.iss4 : PNP.iss7;
  const keys = KEYPARTS[side];
  const xs=L.map(a=>a[4]), ys=L.map(a=>a[5]);
  const minX=Math.min(...xs)-250, maxX=Math.max(...xs)+250, minY=Math.min(...ys)-250, maxY=Math.max(...ys)+250;
  const W=maxX-minX, H=maxY-minY;
  const X=x=>x-minX, Y=y=>maxY-y;
  const now = sideNow(side, SIM.t);
  const chainLive = !/no lock|reset|unconfigured|no output/.test(now.lock);
  let s=`<svg viewBox="0 0 ${W} ${H}" style="width:100%;display:block;background:#0f3d24;border-radius:8px" role="img" aria-label="${side} main board drawn from pick-and-place data">
   <rect x="20" y="20" width="${W-40}" height="${H-40}" rx="60" fill="#145a33" stroke="#c9b25a" stroke-width="10" stroke-dasharray="40 25"/>`;
  // bottom side first (faded), then top
  for (const pass of ['B','T']) for (const a of L){
    const [ref,val,pkg,layer,x,y,rot] = a; if (layer!==pass) continue;
    let [w,h] = PKG[pkg] || (/^[RCL]/.test(ref)?[60,30]:[120,80]);
    if (rot===90||rot===270) [w,h]=[h,w];
    const k = keys[ref]; const sel = D.picked[side]===ref;
    const isIC = /^(U|X)/.test(ref) && w>100;
    const fill = layer==='B' ? 'rgba(200,200,190,.10)' : k ? (k==='rx'?'#2f6db3':k==='tx'?'#8a4fb3':k==='fpga'?'#b3772f':'#4f9a8a') : isIC ? '#26282b' : '#bfb59a';
    s+=`<g class="rd23chip" data-side="${side}" data-ref="${ref}" style="cursor:${isIC?'pointer':'default'}"><rect x="${X(x)-w/2}" y="${Y(y)-h/2}" width="${w}" height="${h}" rx="${isIC?14:3}" fill="${fill}" ${sel?'stroke="#ffd84a" stroke-width="22"':k?'stroke="#e8e4d8" stroke-width="6"':''} ${k&&chainLive?'':''}><title>${ref} ${esc(val)} (${pkg}, ${layer==='T'?'top':'bottom'}) at ${x}, ${y} mil</title></rect>`;
    if (isIC && w>150) s+=`<text x="${X(x)}" y="${Y(y)+ (h>300?20:12)}" text-anchor="middle" font-size="${h>300?92:64}" fill="#f2efe6" style="pointer-events:none">${ref}</text>`;
    if (k && w>150) s+=`<text x="${X(x)}" y="${Y(y)+(h>300?120:90)}" text-anchor="middle" font-size="66" fill="#ffe9a8" style="pointer-events:none">${esc(val.replace('EPCE30F484','EP4CE30').replace('ADSP-21262SKSTZ200','ADSP-21262'))}</text>`;
    s+='</g>';
  }
  // signal path arrows along the key parts (live colour)
  const pos = r=>{ const a=L.find(q=>q[0]===r); return a? [X(a[4]),Y(a[5])] : null; };
  const chain = side==='before' ? [['U1','U7'],['U4','U7'],['U7','U3'],['U3','U13'],['U13','U16']] : [['U1','U9'],['U4','U9'],['U9','U7'],['U7','U3'],['U3','U13']];
  const col = chainLive ? '#ffd84a' : '#ff5a4a';
  chain.forEach(([a,b])=>{ const p=pos(a), q=pos(b); if(p&&q) s+=`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${col}" stroke-width="18" stroke-dasharray="60 40" opacity=".85" style="pointer-events:none"/>`; });
  s+=`<text x="60" y="${H-60}" font-size="110" fill="#e8e4d8">${side==='before'?'AMS16A-3 iss4 (pre-3G)':'AMS16A-3 iss7 (3G)'} · ${L.length} placements · outline ${inf ? 'from part extents' : ''}</text></svg>`;
  return s;
}

