/* ---------------- shared controls ---------------- */
const SCEN = [['steady','Steady (both locked)'],['swap','Source change at 50 ms'],['input','INPUT switch at 50 ms'],['boot','Power-up at 0 s'],['fpga','FPGA reload at 50 ms']];
function fmtOptions(sel){ return ['3GA','3GB','HD','SD'].map(g=>`<optgroup label="${g==='3GA'?'3G level A':g==='3GB'?'3G level B':g}">${FORMATS.filter(f=>f.std===g).map(f=>`<option value="${f.id}" ${f.id===sel?'selected':''}>${f.name}</option>`).join('')}</optgroup>`).join(''); }
