function chipBox(x,y,w,name,sub,left,right,pinH){
  pinH = pinH||16; const h = Math.max(left.length,right.length)*pinH+34;
  let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="var(--panel2)" stroke="var(--ink)" stroke-width="1.4"/><text x="${x+w/2}" y="${y+15}" text-anchor="middle" font-size="12" font-weight="700" fill="var(--ink)">${name}</text><text x="${x+w/2}" y="${y+28}" text-anchor="middle" font-size="9.5" fill="var(--ink2)">${sub}</text>`;
  left.forEach((p,i)=>{ const yy=y+42+i*pinH; s+=`<line x1="${x-14}" y1="${yy}" x2="${x}" y2="${yy}" stroke="var(--ink)"/><text x="${x+4}" y="${yy+3.5}" font-size="9.5" fill="var(--ink)">${p}</text>`; });
  right.forEach((p,i)=>{ const yy=y+42+i*pinH; s+=`<line x1="${x+w}" y1="${yy}" x2="${x+w+14}" y2="${yy}" stroke="var(--ink)"/><text x="${x+w-4}" y="${yy+3.5}" text-anchor="end" font-size="9.5" fill="var(--ink)">${p}</text>`; });
  return s;
}
const wire=(pts,lab,col)=>`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${col||'var(--accent2)'}" stroke-width="1.4"/>${lab?`<text x="${pts[0][0]+3}" y="${pts[0][1]-3}" font-size="9" fill="var(--accent2)">${lab}</text>`:''}`;
