/* ======================================================================
   TAB: Software — live main loops, reset state machine, register maps
   ====================================================================== */
function curStep(O, steps, t){
  const s = at(O.mcu, t); if (!s || t>s.t1) return {kind:'none'};
  if (s.kind!=='pass') return {kind:s.kind, label:s.label};
  const tot=steps.reduce((q,x)=>q+x[1],0); let acc=s.t0;
  for (let i=0;i<steps.length;i++){ const d=(s.t1-s.t0)*steps[i][1]/tot; if (t<acc+d) return {kind:'pass', i, s}; acc+=d; }
  return {kind:'pass', i:steps.length-1, s};
}
function loopList(steps, cur, boot, title){
  const items = steps.map(([nm,ms],i)=>`<li ${cur.kind==='pass'&&cur.i===i?'class="hl"':''}>${esc(nm)} <span class="muted">≈${ms} ms</span></li>`).join('');
  return `<h3>${title}</h3>${cur.kind!=='pass'&&cur.kind!=='none'?`<div class="hl small" style="padding:3px 6px">${esc(cur.label)}</div>`:''}<ol class="small mono" style="margin:4px 0 0;padding-left:20px">${items}</ol>`;
}
