function gspiBytes(r22){
  const rows = [
    ['alteraSpiWrite(0x11, 0x01)','0x11 0x01','gspiSelect(GS2970A_SELECT): the FPGA drops RCVR_CS_N'],
    ['gspiWriteWord(0x0022 | 0x8000 | 0x1000)','0x90 0x22','command: read flag (bit15) + auto-increment (bit12) + 12-bit address'],
    ['gspiReadWord()','0x'+((r22>>8)&255).toString(16).toUpperCase().padStart(2,'0')+' 0x'+(r22&255).toString(16).toUpperCase().padStart(2,'0'),'RASTER_STRUC_4 — the word the firmware keeps'],
    ['gspiReadWord()','xx xx','“Gennum datasheet says we must read at least 2 words … So, we read 2 words and discard the second.”'],
    ['alteraSpiWrite(0x11, 0x00)','0x11 0x00','gspiSelect(ALTERA_CS_NONE)'],
  ];
  return `<table class="kv"><tr><th>Call</th><th>Bytes on PA1/PA0</th><th>Note</th></tr>${rows.map(r=>`<tr><td class="mono">${r[0]}</td><td class="mono">${r[1]}</td><td class="small">${r[2]}</td></tr>`).join('')}</table>
   <p class="small muted">10 bytes ≈ 80 bit-banged clocks plus call overhead ≈ ${(C.GSPI*1e6).toFixed(0)} µs ${inf('≈14 AVR cycles per bit at 4.9152 MHz')}. gs2970AReadVidInfo() does this three times when locked, set1001Flag() once more: about 1 ms of every 3G pass, which the pre-3G loop did not spend.</p>`;
}

